/*
 * A102092  a(n)< a(n+1) and: each digit is the absolute difference of the
 *          previous two; each digit is the absolute difference of the next
 *          two; each digit is the absolute difference of its two neighbors.
 * https://oeis.org/A102092
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   a(n) is the decimal integer whose digits are generated by d0 =
 *            1, d1 = 1 if n % 3 != 2, otherwise 0, and for i ≥ 2: d_i =
 *            d_{i-2} XOR d_{i-1}. Thus a(0)=0, a(1)=1, a(2)=10, a(3)=110,
 *            a(4)=1101, …
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 10, u64 n <= 11, u128 n <= 11,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;

    if (n == 1)
        return (seq_t)1;

    seq_t result = 0;
    /* first digit is always 1 */
    result = result * (seq_t)10 + (seq_t)1;

    /* second digit depends on n modulo 3 */
    seq_t a1 = (n % 3 == 2) ? (seq_t)0 : (seq_t)1;
    result = result * (seq_t)10 + a1;

    seq_t prev2 = (seq_t)1;
    seq_t prev1 = a1;

    for (idx_t i = 2; i < n; ++i) {
        seq_t digit = prev2 ^ prev1;          /* |prev2 - prev1| for 0/1 digits */
        result = result * (seq_t)10 + digit;
        prev2 = prev1;
        prev1 = digit;
    }
    return result;
}
